MAX_ZIP_ENTRIES = 2000
MAX_MEMBER_BYTES = 20 * 1024 * 1024
MAX_TOTAL_BYTES = 200 * 1024 * 1024

UI_SCOPES = ("full-stack", "frontend-only")
ALL_SCOPES = UI_SCOPES + ("backend-only", "integration")

