class PoPackageError(Exception):
    """A condition the operator must fix. The message is plain language, never a trace."""


# ── Repository and configuration ─────────────────────────────────────────────


def resolve_repo(cli_repo: str | None = None) -> Path:
    """--repo, then PO_PACKAGE_REPO, then the git toplevel of this file."""
    candidate = cli_repo or os.environ.get("PO_PACKAGE_REPO")
    if candidate:
        path = Path(candidate).expanduser().resolve()
        if not path.is_dir():
            raise PoPackageError(f"The repository path does not exist: {path}")
        return path
    try:
        out = subprocess.run(
            ["git", "-C", str(HERE), "rev-parse", "--show-toplevel"],
            capture_output=True, text=True, timeout=15, check=False,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise PoPackageError(f"Cannot locate the repository (git unavailable: {exc}). Pass --repo.") from exc
    if out.returncode != 0 or not out.stdout.strip():
        raise PoPackageError("Cannot locate the repository. Pass --repo or set PO_PACKAGE_REPO.")
    return Path(out.stdout.strip())


def merge_config(base: dict, over: dict) -> dict:
    out = dict(base)
    for key, value in over.items():
        if isinstance(value, dict) and isinstance(out.get(key), dict):
            out[key] = merge_config(out[key], value)
        else:
            out[key] = value
    return out


def load_config(path: Path | None = None) -> dict:
    """Defaults overlaid with the project config. Unresolved placeholders are an error."""
    cfg_path = path or (HERE / CONFIG_NAME)
    if not cfg_path.exists():
        raise PoPackageError(f"Missing configuration file: {cfg_path}")
    raw = cfg_path.read_text(encoding="utf-8")
    leftover = sorted(set(re.findall(r"\{\{[A-Z0-9_]+\}\}", raw)))
    if leftover:
        raise PoPackageError(
            f"{cfg_path.name} still carries unresolved placeholders ({', '.join(leftover)}). "
            "SETUP --generate resolves them; outside a materialised project pass --config."
        )
    try:
        data = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise PoPackageError(f"{cfg_path.name} is not valid JSON: {exc}") from exc
    if not isinstance(data, dict):
        raise PoPackageError(f"{cfg_path.name} must hold a JSON object.")
    cfg = merge_config(DEFAULT_CONFIG, data)
    cards = cfg["design_system"]["code_cards"]
    for key in ("dir", "rebuild_command"):  # tolerate the string "null" where JSON null was meant
        if isinstance(cards.get(key), str) and cards[key].strip().lower() in ("", "null", "none"):
            cards[key] = None
    return cfg


def feature_id_re(cfg: dict) -> re.Pattern[str]:
    try:
        return re.compile(cfg["features"]["id_pattern"])
    except re.error as exc:
        raise PoPackageError(f"features.id_pattern is not a valid pattern: {exc}") from exc


def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8", errors="replace")


def slugify(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", value.lower()).strip("-")


# ── Journey-first grammar: frontmatter and closed vocabulary ─────────────────

_FM_RE = re.compile(r"\A---\n(.*?)\n---\n?", re.S)
_COMMENT_RE = re.compile(r"<!--.*?-->", re.S)


def split_frontmatter(text: str) -> tuple[str, str]:
    """(frontmatter body, rest). Frontmatter is factory-owned; a PO return may omit it."""
    match = _FM_RE.match(text.lstrip("﻿"))
    if not match:
        return "", text
    return match.group(1), text[match.end():]


def frontmatter_value(frontmatter: str, key: str) -> str | None:
    match = re.search(rf"^{re.escape(key)}:\s*\"?([^\"#\n]*?)\"?\s*(?:#.*)?$", frontmatter, re.M)
    return match.group(1).strip() if match and match.group(1).strip() else None


def section_body(text: str, heading_prefix: str) -> str:
    """Body of the H2 whose line starts with `heading_prefix`, up to the next H2."""
    out: list[str] = []
    inside = False
    for line in text.splitlines():
        if line.startswith("## "):
            inside = line.startswith(heading_prefix)
            continue
        if inside:
            out.append(line)
    return "\n".join(out)


def _table_column(body: str, index: int) -> list[str]:
    values: list[str] = []
    seen_separator = False
    for line in body.splitlines():
        stripped = line.strip()
        if not stripped.startswith("|"):
            seen_separator = False
            continue
        cells = [c.strip() for c in stripped.strip("|").split("|")]
        if all(re.fullmatch(r":?-{2,}:?", c) for c in cells if c):
            seen_separator = True
            continue
        if not seen_separator or index >= len(cells):
            continue
        cell = cells[index].strip("` ")
        if cell and cell != "—":
            values.append(cell)
    return values


def journey_vocab(text: str) -> dict[str, set[str]]:
    """Closed vocabulary a journey declares: personas (§1), concepts + fields (§6), rules (§7)."""
    _fm, body = split_frontmatter(text)
    body = _COMMENT_RE.sub("", body)
    sec6 = section_body(body, "## Section 6:")
    return {
        "personas": set(_table_column(section_body(body, "## Section 1:"), 0)),
        "concepts": {m.group(1).strip() for m in re.finditer(r"^###\s+(.+?)\s*$", sec6, re.M)},
        "fields": set(_table_column(sec6, 0)),
        "rules": set(_table_column(section_body(body, "## Section 7:"), 1)),
    }


def empty_vocab() -> dict[str, set[str]]:
    return {"personas": set(), "concepts": set(), "fields": set(), "rules": set()}


def spec_features(repo: Path, cfg: dict) -> list[str]:
    """Feature ids that have a journey in the repo, honouring include/exclude."""
    root = repo / cfg["features"]["spec_root"]
    pattern = feature_id_re(cfg)
    include = set(cfg["features"].get("include") or [])
    exclude = set(cfg["features"].get("exclude") or [])
    found: list[str] = []
    if not root.is_dir():
        return found
    for entry in sorted(root.iterdir()):
        if not entry.is_dir() or not pattern.match(entry.name):
            continue
        if (include and entry.name not in include) or entry.name in exclude:
            continue
        if (entry / "user_journey.md").exists():
            found.append(entry.name)
    return found


def load_glossary(repo: Path, cfg: dict) -> dict[str, set[str]]:
    """Union of the vocabulary of every journey currently in the repo — the live truth."""
    glossary = empty_vocab()
    root = repo / cfg["features"]["spec_root"]
    for feature_id in spec_features(repo, cfg):
        vocab = journey_vocab(read_text(root / feature_id / "user_journey.md"))
        for key in glossary:
            glossary[key] |= vocab[key]
    return glossary


# ── HTML: external references and nesting-safe section scanner ───────────────


def external_refs(html: str) -> list[str]:
    return re.findall(r"""(?:src|href)\s*=\s*["'](https?://[^"']+)["']""", html, re.I)


def allowed_hosts(repo: Path, cfg: dict) -> set[str]:
    """Hosts the framework's own CODESIGN templates load, plus the project's allowlist.

    Derived at run time so a factory-generated mock can never be red by construction.
    """
    hosts = {h.lower() for h in (cfg["mock"].get("allowed_external_hosts") or [])}
    templates = repo / ".context" / "templates" / "codesign"
    if templates.is_dir():
        for html_file in sorted(templates.glob("*.html")):
            for url in external_refs(read_text(html_file)):
                host = urlparse(url).hostname
                if host:
                    hosts.add(host.lower())
    return hosts


def disallowed_refs(html: str, hosts: set[str]) -> list[str]:
    bad: list[str] = []
    for url in external_refs(html):
        host = (urlparse(url).hostname or "").lower()
        if host not in hosts:
            bad.append(url)
    return bad


class _SectionScanner(HTMLParser):
    """Top-level `<section ATTR=…>` blocks. Nested sections never split a block."""

    def __init__(self, source: str, attr: str) -> None:
        super().__init__(convert_charrefs=True)
        self._source = source
        self._attr = attr
        self._starts = [0]
        for line in source.splitlines(keepends=True):
            self._starts.append(self._starts[-1] + len(line))
        self._depth = 0
        self._open: dict | None = None
        self.blocks: list[dict] = []

    def _offset(self) -> int:
        line, col = self.getpos()
        return self._starts[line - 1] + col

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag != "section":
            return
        if self._open is not None:
            self._depth += 1
            return
        attributes = dict(attrs)
        if self._attr not in attributes:
            return
        name = (attributes.get(self._attr) or "").strip()
        self._open = {
            "id": (attributes.get("id") or "").strip() or slugify(name),
            "name": name or (attributes.get("id") or "").strip(),
            "group": (attributes.get("data-group") or "").strip(),
            "start": self._offset(),
        }
        self._depth = 0

    def handle_endtag(self, tag: str) -> None:
        if tag != "section" or self._open is None:
            return
        if self._depth > 0:
            self._depth -= 1
            return
        close = self._source.find(">", self._offset())
        end = close + 1 if close != -1 else len(self._source)
        block = self._open
        block["html"] = self._source[block.pop("start"):end]
        self.blocks.append(block)
        self._open = None


def scan_sections(html: str, attr: str) -> list[dict]:
    """[{id, name, group, html}] for each top-level `<section {attr}="…">`."""
    scanner = _SectionScanner(html, attr)
    scanner.feed(html)
    scanner.close()
    return scanner.blocks


def tokens_declared(html: str) -> bool:
    """Design tokens may live in a root CSS block or in a utility-framework config block."""
    if re.search(r":root\s*\{[^}]*--[a-zA-Z]", html, re.S):
        return True
    return bool(re.search(r"tailwind\.config\s*=", html))


# ── Registry and codebase inventory ──────────────────────────────────────────


def load_json(path: Path, default):
    if not path.exists():
        return default
    try:
        return json.loads(read_text(path))
    except json.JSONDecodeError as exc:
        raise PoPackageError(f"{path} is not valid JSON: {exc}") from exc


def registry_components(repo: Path, cfg: dict) -> list[dict]:
    data = load_json(repo / cfg["design_system"]["component_registry"], {})
    return list(data.get("components") or []) if isinstance(data, dict) else []


def inventory_ui_components(repo: Path, cfg: dict) -> dict[str, dict]:
    """{name: artifact} for the codebase inventory entries that are UI components."""
    data = load_json(repo / cfg["design_system"]["codebase_inventory"], {})
    artifacts = data.get("artifacts") or [] if isinstance(data, dict) else []
    return {
        a["name"]: a for a in artifacts
        if isinstance(a, dict) and a.get("name") and a.get("type") == "ui_component"
    }


# ── Zip safety ───────────────────────────────────────────────────────────────


def _member_problem(info: zipfile.ZipInfo) -> str | None:
    name = info.filename
    parts = PurePosixPath(name.replace("\\", "/")).parts
    if name.startswith(("/", "\\")) or re.match(r"^[A-Za-z]:", name):
        return f"absolute path: {name}"
    if ".." in parts:
        return f"path escapes the archive: {name}"
    if (info.external_attr >> 16) & 0o170000 == 0o120000:
        return f"symbolic link: {name}"
    if info.file_size > MAX_MEMBER_BYTES:
        return f"oversized member ({info.file_size} bytes): {name}"
    return None


def zip_problems(zip_path: Path) -> list[str]:
    """Reasons this archive must not be extracted. Empty list = safe."""
    try:
        with zipfile.ZipFile(zip_path) as archive:
            infos = archive.infolist()
    except (zipfile.BadZipFile, OSError) as exc:
        return [f"not a readable zip: {exc}"]
    problems = [p for p in (_member_problem(i) for i in infos) if p]
    if len(infos) > MAX_ZIP_ENTRIES:
        problems.append(f"too many entries ({len(infos)} > {MAX_ZIP_ENTRIES})")
    if sum(i.file_size for i in infos) > MAX_TOTAL_BYTES:
        problems.append(f"archive expands beyond {MAX_TOTAL_BYTES} bytes")
    return problems
